function validate([nums]) {
  if (!Array.isArray(nums) || nums.length > 20) return 'nums has at most 20 values.';
  for (let i = 0; i < nums.length; i++) {
    if (!Number.isInteger(nums[i]) || nums[i] < -2147483648 || nums[i] > 2147483647) return 'Each value must be a 32-bit integer.';
    if (i > 0 && nums[i] <= nums[i - 1]) return 'nums must be strictly increasing (sorted, no duplicates).';
  }
  return null;
}

