function summaryRanges(nums) {
  const present = new Set(nums);
  const result = [];
  for (const value of nums) {
    if (present.has(value - 1)) continue;
    let last = value;
    while (present.has(last + 1)) last++;
    result.push(last === value ? `${value}` : `${value}->${last}`);
  }
  return result;
}

