function generate(rand, size) {
  const MIN = -2147483648, MAX = 2147483647;
  const n = size === 'large' ? 20 : Math.floor(rand() * 9);
  // Pick a starting point: sometimes at the bottom edge, sometimes small, sometimes anywhere.
  const mode = rand();
  let value = mode < 0.15 ? MIN : mode < 0.6 ? Math.floor(rand() * 21) - 10 : MIN + Math.floor(rand() * 2 ** 31);
  const nums = [];
  for (let i = 0; i < n && value <= MAX; i++) {
    nums.push(value);
    const step = rand();
    // Mostly +1 steps to build runs, otherwise a small or a huge jump.
    const gap = step < 0.6 ? 1 : step < 0.9 ? 2 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 2 ** 28);
    value += gap;
  }
  // Sometimes finish exactly at the top edge.
  if (nums.length && nums.length < n && rand() < 0.5 && nums[nums.length - 1] < MAX) nums.push(MAX);
  if (size !== 'large' && rand() < 0.2 && nums.length && nums[nums.length - 1] < MAX - 1) nums.push(MAX - 1, MAX);
  return [nums.slice(0, 20)];
}
